#include <stdlib.h>
#include <string.h>

// Auction algorithm with epsilon scaling for min-cost assignment.
// cost: row-major double array n*n. Returns assignment[row]=col.
int* auction(const double* cost, int n) {
    double* p = (double*)calloc(n, sizeof(double));
    int* person_to_obj = (int*)malloc(n * sizeof(int));
    int* obj_to_person = (int*)malloc(n * sizeof(int));
    int* unassigned = (int*)malloc(n * sizeof(int));
    int* unassigned2 = (int*)malloc(n * sizeof(int));

    // initial epsilon
    double maxc = 0.0;
    for (int k = 0; k < n*n; k++) if (cost[k] > maxc) maxc = cost[k];
    double eps = maxc > 0 ? maxc : 1.0;

    while (eps > 1e-9) {
        // reset assignment, keep prices
        for (int i = 0; i < n; i++) { person_to_obj[i] = -1; obj_to_person[i] = -1; }
        int nu = 0;
        for (int i = 0; i < n; i++) unassigned[nu++] = i;

        while (nu > 0) {
            int i = unassigned[--nu];
            const double* row = cost + (size_t)i * n;
            double best = 1e300, second = 1e300;
            int best_j = -1;
            for (int j = 0; j < n; j++) {
                double val = row[j] - p[j];
                if (val < best) { second = best; best = val; best_j = j; }
                else if (val < second) { second = val; }
            }
            double bid = second - best + eps;
            p[best_j] += bid;
            int prev = obj_to_person[best_j];
            obj_to_person[best_j] = i;
            person_to_obj[i] = best_j;
            if (prev != -1) {
                person_to_obj[prev] = -1;
                unassigned[nu++] = prev;
            }
        }
        eps *= 0.1;
    }

    int* assignment = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) assignment[i] = person_to_obj[i];

    free(p); free(person_to_obj); free(obj_to_person); free(unassigned); free(unassigned2);
    return assignment;
}
